n,c = list(map(int,input().split()))
d = [0.0]*(c+1)
names = input().split()
for i in range(n):
    a = list(map(int,input().split()))
    t = 0
    for j in range(c):
        d[j]+=(a[j]-(a[j]%10))/10
        t+=(a[j]%10)/10
    d[-1]+=t
m = 0
for i in range(c+1):
    if d[i]>d[m]:
        m = i
total = 0
for i in range(c+1):
    if d[i]==d[m]:
        total+=1
if total!=1 or m==c:
    print("Revote")
else:
    print(names[m])
